function newCompany(i){let nm=names[i%names.length],id='ai'+i;return {id,name:nm,ticker:nm.replace(/[^A-Z]/gi,'').slice(0,4).toUpperCase(),sector:sectors[i%sectors.length],shares:10000,price:Math.round(600+Math.random()*8000),value:0,owned:0,ownedByPlayer:false,listed:true,generated:true,change:0,shareholders:[],cash:500000+Math.random()*2500000,parcels:Math.round(80+Math.random()*1800),lockers:Math.round(Math.random()*60),depots:1+Math.floor(Math.random()*5),vans:2+Math.floor(Math.random()*40),employees:8+Math.floor(Math.random()*100),growth:.5+Math.random()*2.5,parentId:null,subs:[],level:1,expansionStrategy:'balanced',expansionPace:'normal',hiringPolicy:'normal',investmentBudget:35,targetRegion:'Polska'};}
function seed(){let firms=[];for(let i=0;i<8;i++){let c=newCompany(i);c.shareholders=[{name:'Założyciel',shares:3000},{name:'Fundusz Północny',shares:2500},{name:'Inwestor prywatny',shares:2000},{name:'Fundusz Rozwoju',shares:1500},{name:'Drobni inwestorzy',shares:1000}];c.value=c.price*c.shares;firms.push(c)}return {day:1,cash:500000,bank:500000,debt:0,companies:firms,assets:[],activity:[{day:1,title:'Start działalności',desc:'Masz 500 000 zł kapitału. Nie posiadasz jeszcze żadnej infrastruktury.'}],history:[500000],speed:1,paused:false,selected:'overview',nextCompany:4,playerShares:{},mapCenter:[52.1,19.4]}}
let s;try{s=JSON.parse(localStorage.getItem('logistics_tycoon_v2'))||seed()}catch(e){s=seed()}
if(!Array.isArray(s.assets))s.assets=[];if(!Array.isArray(s.routes))s.routes=[];if(!Array.isArray(s.companies))s.companies=seed().companies;s.companies.forEach(c=>{if(!Array.isArray(c.shareholders))c.shareholders=[{name:'Założyciel',shares:Math.floor(c.shares*.3)},{name:'Fundusz inwestycyjny',shares:Math.floor(c.shares*.25)},{name:'Inwestorzy indywidualni',shares:c.shares-Math.floor(c.shares*.55)}];if(!c.value)c.value=c.price*c.shares});
if(!s.playerShares)s.playerShares={};s.companies.forEach(co=>{if(co.ownedByPlayer)co.listed=true;});if(!Array.isArray(s.upgrades))s.upgrades=[];if(!Array.isArray(s.contracts))s.contracts=[];if(!s.staff)s.staff={drivers:0,dispatchers:0,mechanics:0};if(!Number.isFinite(s.debt))s.debt=0;
function reconcileShareholders(company){
 const total=Math.max(1,Math.floor(company.shares||10000));
 let player=Math.max(0,Math.floor(s.playerShares[company.id]||0));
 let treasury=Math.max(0,Math.floor(company.treasury||0));
 let holders=(company.shareholders||[]).filter(x=>x&&x.shares>0).map(x=>({name:x.name||'Inwestor',shares:Math.max(0,Math.floor(x.shares))}));
 if(player+treasury>total){let excess=player+treasury-total;let cut=Math.min(treasury,excess);treasury-=cut;excess-=cut;player=Math.max(0,player-excess);s.playerShares[company.id]=player;company.treasury=treasury;}
 let available=total-player-treasury, sum=holders.reduce((n,x)=>n+x.shares,0);
 if(sum>available){let factor=available/sum;holders=holders.map(x=>({...x,shares:Math.floor(x.shares*factor)}));sum=holders.reduce((n,x)=>n+x.shares,0);}
 let remainder=available-sum;
 if(remainder>0){let existing=holders.find(x=>x.name==='Pozostali inwestorzy');if(existing)existing.shares+=remainder;else holders.push({name:'Pozostali inwestorzy',shares:remainder});}
 company.shareholders=holders.filter(x=>x.shares>0);company.treasury=treasury;
}
s.companies.forEach(reconcileShareholders);
function save(){localStorage.setItem('logistics_tycoon_v2',JSON.stringify(s))}
function log(title,desc){s.activity.unshift({day:s.day,title,desc});s.activity=s.activity.slice(0,30)}
