function countryChecklist(containerId,selected,filter){let el=$(containerId);if(!el)return;let chosen=new Set(selected||[]),items=geoMarkets.filter(g=>!filter||filter==='Cały świat'||g.continent===filter).flatMap(g=>g.countries.map(country=>({country,continent:g.continent})));el.innerHTML='<div class="country-toolbar"><b>'+items.length+' krajów</b><button type="button" class="btn" onclick="toggleAllCountries(\''+containerId+'\',true)">Zaznacz wszystkie</button><button type="button" class="btn" onclick="toggleAllCountries(\''+containerId+'\',false)">Odznacz wszystkie</button></div><div class="country-check-grid">'+items.map(x=>'<label class="country-option"><input type="checkbox" class="'+(containerId==='countryChoices'?'country-check':'edit-country-check')+'" value="'+x.country+'" ' +(chosen.has(x.country)?'checked':'')+(containerId==='editCountryChoices'?' onchange="updateEditCountrySelection()"':containerId==='countryChoices'?' onchange="updateNewSubsidiaryCountrySelection()"':'')+'> <span>'+x.country+'</span><small>'+x.continent+'</small></label>').join('')+'</div>'}
window.toggleAllCountries=function(containerId,checked){let el=$(containerId);if(el)el.querySelectorAll('input[type=checkbox]').forEach(x=>x.checked=checked);if(containerId==='editCountryChoices')updateEditCountrySelection();if(containerId==='countryChoices')window.updateNewSubsidiaryCountrySelection()};
window.updateEditCountrySelection=function(){let filter=$('editSubContinent')?.value||'Cały świat',visible=new Set(geoMarkets.filter(g=>filter==='Cały świat'||g.continent===filter).flatMap(g=>g.countries)),checked=new Set([...document.querySelectorAll('.edit-country-check:checked')].map(x=>x.value));editCountrySelection=editCountrySelection.filter(x=>!visible.has(x));checked.forEach(x=>editCountrySelection.push(x));editCountrySelection=[...new Set(editCountrySelection)]};

function managementPanelContent(targetId){let list=targetId?[findGroupNode(targetId)].filter(Boolean):ownedCompanies();if(!list.length)return '<section class="panel"><div class="ph"><b>PANEL ZARZĄDZANIA GRUPĄ</b><span class="tag warn">ZABLOKOWANY</span></div><p class="muted" style="font-size:10px">Zdobądź ponad 50% udziałów w dowolnej spółce, aby odblokować jej panel zarządzania. Przejęta firma nadal samodzielnie prowadzi codzienną działalność.</p></section>';return list.map(c=>'<section class="panel"><div class="ph"><b>⚙ ZARZĄDZANIE · '+c.name+'</b><span class="tag good">KONTROLA '+(100*(s.playerShares[c.id]||0)/c.shares).toFixed(1)+'%</span></div><div class="grid2"><div><div class="field"><label>STRATEGIA EKSPANSJI</label><select onchange="setCompanyPolicy(\''+c.id+'\',\'expansionStrategy\',this.value)"><option value="balanced" '+(c.expansionStrategy==='balanced'?'selected':'')+'>Zrównoważona</option><option value="lockers" '+(c.expansionStrategy==='lockers'?'selected':'')+'>Sieć automatów paczkowych</option><option value="depots" '+(c.expansionStrategy==='depots'?'selected':'')+'>Centra i sortownie</option><option value="fleet" '+(c.expansionStrategy==='fleet'?'selected':'')+'>Flota i transport</option><option value="regional" '+(c.expansionStrategy==='regional'?'selected':'')+'>Ekspansja regionalna</option></select></div><div class="field"><label>TEMPO ROZWOJU</label><select onchange="setCompanyPolicy(\''+c.id+'\',\'expansionPace\',this.value)"><option value="slow" '+(c.expansionPace==='slow'?'selected':'')+'>Ostrożne</option><option value="normal" '+(c.expansionPace==='normal'?'selected':'')+'>Normalne</option><option value="fast" '+(c.expansionPace==='fast'?'selected':'')+'>Agresywne</option></select></div></div><div><div class="field"><label>POLITYKA ZATRUDNIENIA</label><select onchange="setCompanyPolicy(\''+c.id+'\',\'hiringPolicy\',this.value)"><option value="lean" '+(c.hiringPolicy==='lean'?'selected':'')+'>Oszczędna</option><option value="normal" '+(c.hiringPolicy==='normal'?'selected':'')+'>Normalna</option><option value="growth" '+(c.hiringPolicy==='growth'?'selected':'')+'>Zatrudniaj pod wzrost</option></select></div><div class="field"><label>BUDŻET INWESTYCYJNY · '+c.investmentBudget+'% PRZYCHODÓW</label><input type="range" min="5" max="80" step="5" value="'+c.investmentBudget+'" oninput="setCompanyPolicy(\''+c.id+'\',\'investmentBudget\',+this.value)"></div></div></div><div class="field"><label>OBSZAR EKSPANSJI</label><select onchange="setCompanyPolicy(\''+c.id+'\',\'targetRegion\',this.value)">'+['Cały świat',...geoMarkets.map(g=>g.continent),...allWorldCountries].map(x=>'<option '+((c.targetRegion||'Polska')===x?'selected':'')+'>'+x+'</option>').join('')+'</select></div><div class="notice">Firma samodzielnie rekrutuje, kupuje pojazdy i rozbudowuje infrastrukturę. Aktualnie: '+number(c.employees)+' pracowników · '+number(c.vans)+' pojazdów · '+number(c.depots)+' centrów · '+number(c.lockers)+' automatów · gotówka '+money(c.cash)+'.</div><div class="ph"><b>SPÓŁKI CÓRKI I RYNKI</b><button class="btn primary" onclick="openSubsidiary(\''+c.id+'\')">+ Nowa spółka córka</button></div><div class="muted" style="font-size:9px">'+(c.subs||[]).map(x=>x.name+' — '+x.countries.join(", ")).join("<br>")+'</div></section>').join('')}
